    /// <summary>
    /// Describes an update for a destination in Amazon OpenSearch Service. RoleARN -&gt; (string) The Amazon Resource Name (ARN) of the IAM role to be assumed by Firehose for calling the Amazon OpenSearch Service Configuration API and for indexing documents. For more information, see Grant Firehose Access to an Amazon S3 Destination and Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ DomainARN -&gt; (string) The ARN of the Amazon OpenSearch Service domain. The IAM role must have permissions for DescribeDomain , DescribeDomains , and DescribeDomainConfig after assuming the IAM role specified in RoleARN . For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Specify either ClusterEndpoint or DomainARN . Constraints: o min: 1 o max: 512 o pattern: arn:.*:es:[a-zA-Z0-9\-]+:\d{12}:do- main/[a-z][-0-9a-z]{2,27} ClusterEndpoint -&gt; (string) The endpoint to use when communicating with the cluster. Specify either this ClusterEndpoint or the DomainARN field. Constraints: o min: 1 o max: 512 o pattern: https:.* IndexName -&gt; (string) The Elasticsearch index name. Constraints: o min: 1 o max: 80 o pattern: .* TypeName -&gt; (string) The Elasticsearch type name. For Elasticsearch 6.x, there can be only one type per index. If you try to specify a new type for an existing index that already has another type, Firehose returns an error during runtime. If you upgrade Elasticsearch from 6.x to 7.x and dont update your Firehose stream, Firehose still delivers data to Elastic- search with the old index name and type name. If you want to up- date your Firehose stream with a new index name, provide an empty string for TypeName . Constraints: o min: 0 o max: 100 o pattern: .* IndexRotationPeriod -&gt; (string) The Elasticsearch index rotation period. Index rotation appends a timestamp to IndexName to facilitate the expiration of old data. For more information, see Index Rotation for the Amazon OpenSearch Service Destination . Default value is OneDay . Possible values: o NoRotation o OneHour o OneDay o OneWeek o OneMonth BufferingHints -&gt; (structure) The buffering options. If no value is specified, Elasticsearch- BufferingHints object default values are used. IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The default value is 300 (5 minutes). Constraints: o min: 0 o max: 900 SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MBs, before delivering it to the destination. The default value is 5. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typically ingest data at 1 MB/sec, the value should be 10 MB or higher. Constraints: o min: 1 o max: 100 RetryOptions -&gt; (structure) The retry behavior in case Firehose is unable to deliver docu- ments to Amazon OpenSearch Service. The default value is 300 (5 minutes). DurationInSeconds -&gt; (integer) After an initial failure to deliver to Amazon OpenSearch Ser- vice, the total amount of time during which Firehose retries delivery (including the first attempt). After this time has elapsed, the failed documents are written to Amazon S3. De- fault value is 300 seconds (5 minutes). A value of 0 (zero) results in no retries. Constraints: o min: 0 o max: 7200 S3Update -&gt; (structure) The Amazon S3 destination. RoleARN -&gt; (string) The Amazon Resource Name (ARN) of the Amazon Web Services credentials. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ BucketARN -&gt; (string) The ARN of the S3 bucket. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Name- spaces . Constraints: o min: 1 o max: 2048 o pattern: arn:.*:s3:::[\w\.\-]{1,255} Prefix -&gt; (string) The "YYYY/MM/DD/HH" time format prefix is automatically used for delivered Amazon S3 files. You can also specify a custom prefix, as described in Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* ErrorOutputPrefix -&gt; (string) A prefix that Firehose evaluates and adds to failed records before writing them to S3. This prefix appears immediately following the bucket name. For information about how to spec- ify this prefix, see Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* BufferingHints -&gt; (structure) The buffering option. If no value is specified, BufferingH- ints object default values are used. SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MiBs, be- fore delivering it to the destination. The default value is 5. This parameter is optional but if you specify a value for it, you must also specify a value for Inter- valInSeconds , and vice versa. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typi- cally ingest data at 1 MiB/sec, the value should be 10 MiB or higher. Constraints: o min: 1 o max: 128 IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The de- fault value is 300. This parameter is optional but if you specify a value for it, you must also specify a value for SizeInMBs , and vice versa. Constraints: o min: 0 o max: 900 CompressionFormat -&gt; (string) The compression format. If no value is specified, the default is UNCOMPRESSED . The compression formats SNAPPY or ZIP cannot be specified for Amazon Redshift destinations because they are not supported by the Amazon Redshift COPY operation that reads from the S3 bucket. Possible values: o UNCOMPRESSED o GZIP o ZIP o Snappy o HADOOP_SNAPPY EncryptionConfiguration -&gt; (structure) The encryption configuration. If no value is specified, the default is no encryption. NoEncryptionConfig -&gt; (string) Specifically override existing encryption information to ensure that no encryption is used. Possible values: o NoEncryption KMSEncryptionConfig -&gt; (structure) The encryption key. AWSKMSKeyARN -&gt; (string) [required] The Amazon Resource Name (ARN) of the encryption key. Must belong to the same Amazon Web Services Region as the destination Amazon S3 bucket. For more informa- tion, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:kms:[a-zA-Z0-9\-]+:\d{12}:(key|alias)/[a-zA-Z_0-9+=,.@\-_/]+ CloudWatchLoggingOptions -&gt; (structure) The CloudWatch logging options for your Firehose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* ProcessingConfiguration -&gt; (structure) The data processing configuration. Enabled -&gt; (boolean) Enables or disables data processing. Processors -&gt; (list) The data processors. (structure) Describes a data processor. NOTE: If you want to add a new line delimiter between records in objects that are delivered to Amazon S3, choose AppendDelimiterToRecord as a processor type. You dont have to put a processor parameter when you select AppendDelimiterToRecord . Type -&gt; (string) [required] The type of processor. Possible values: o RecordDeAggregation o Decompression o CloudWatchLogProcessing o Lambda o MetadataExtraction o AppendDelimiterToRecord Parameters -&gt; (list) The processor parameters. (structure) Describes the processor parameter. ParameterName -&gt; (string) [required] The name of the parameter. Currently the fol- lowing default values are supported: 3 for Num- berOfRetries and 60 for the BufferIntervalIn- Seconds . The BufferSizeInMBs ranges between 0.2 MB and up to 3MB. The default buffering hint is 1MB for all destinations, except Splunk. For Splunk, the default buffering hint is 256 KB. Possible values: o LambdaArn o NumberOfRetries o MetadataExtractionQuery o JsonParsingEngine o RoleArn o BufferSizeInMBs o BufferIntervalInSeconds o SubRecordType o Delimiter o CompressionFormat o DataMessageExtraction ParameterValue -&gt; (string) [required] The parameter value. Constraints: o min: 1 o max: 5120 o pattern: ^(?!\s*$).+ CloudWatchLoggingOptions -&gt; (structure) The CloudWatch logging options for your Firehose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* DocumentIdOptions -&gt; (structure) Indicates the method for setting up document ID. The supported methods are Firehose generated document ID and OpenSearch Ser- vice generated document ID. DefaultDocumentIdFormat -&gt; (string) [required] When the FIREHOSE_DEFAULT option is chosen, Firehose gener- ates a unique document ID for each record based on a unique internal identifier. The generated document ID is stable across multiple delivery attempts, which helps prevent the same record from being indexed multiple times with different document IDs. When the NO_DOCUMENT_ID option is chosen, Firehose does not include any document IDs in the requests it sends to the Ama- zon OpenSearch Service. This causes the Amazon OpenSearch Service domain to generate document IDs. In case of multiple delivery attempts, this may cause the same record to be in- dexed more than once with different document IDs. This option enables write-heavy operations, such as the ingestion of logs and observability data, to consume less resources in the Ama- zon OpenSearch Service domain, resulting in improved perfor- mance. Possible values: o FIREHOSE_DEFAULT o NO_DOCUMENT_ID JSON Syntax: { "RoleARN": "string", "DomainARN": "string", "ClusterEndpoint": "string", "IndexName": "string", "TypeName": "string", "IndexRotationPeriod": "NoRotation"|"OneHour"|"OneDay"|"OneWeek"|"OneMonth", "BufferingHints": { "IntervalInSeconds": integer, "SizeInMBs": integer }, "RetryOptions": { "DurationInSeconds": integer }, "S3Update": { "RoleARN": "string", "BucketARN": "string", "Prefix": "string", "ErrorOutputPrefix": "string", "BufferingHints": { "SizeInMBs": integer, "IntervalInSeconds": integer }, "CompressionFormat": "UNCOMPRESSED"|"GZIP"|"ZIP"|"Snappy"|"HADOOP_SNAPPY", "EncryptionConfiguration": { "NoEncryptionConfig": "NoEncryption", "KMSEncryptionConfig": { "AWSKMSKeyARN": "string" } }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" } }, "ProcessingConfiguration": { "Enabled": true|false, "Processors": [ { "Type": "RecordDeAggregation"|"Decompression"|"CloudWatchLogProcessing"|"Lambda"|"MetadataExtraction"|"AppendDelimiterToRecord", "Parameters": [ { "ParameterName": "LambdaArn"|"NumberOfRetries"|"MetadataExtractionQuery"|"JsonParsingEngine"|"RoleArn"|"BufferSizeInMBs"|"BufferIntervalInSeconds"|"SubRecordType"|"Delimiter"|"CompressionFormat"|"DataMessageExtraction", "ParameterValue": "string" } ... ] } ... ] }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" }, "DocumentIdOptions": { "DefaultDocumentIdFormat": "FIREHOSE_DEFAULT"|"NO_DOCUMENT_ID" } }
    /// </summary>
    [CliOption("--elasticsearch-destination-update")]
    public string? ElasticsearchDestinationUpdate { get; set; }

    /// <summary>
    /// Describes an update for a destination in Amazon OpenSearch Service. RoleARN -&gt; (string) The Amazon Resource Name (ARN) of the IAM role to be assumed by Firehose for calling the Amazon OpenSearch Service Configuration API and for indexing documents. Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ DomainARN -&gt; (string) The ARN of the Amazon OpenSearch Service domain. The IAM role must have permissions for DescribeDomain, DescribeDomains, and DescribeDomainConfig after assuming the IAM role specified in RoleARN. Constraints: o min: 1 o max: 512 o pattern: arn:.*:es:[a-zA-Z0-9\-]+:\d{12}:do- main/[a-z][-0-9a-z]{2,27} ClusterEndpoint -&gt; (string) The endpoint to use when communicating with the cluster. Specify either this ClusterEndpoint or the DomainARN field. Constraints: o min: 1 o max: 512 o pattern: https:.* IndexName -&gt; (string) The Amazon OpenSearch Service index name. Constraints: o min: 1 o max: 80 o pattern: .* TypeName -&gt; (string) The Amazon OpenSearch Service type name. For Elasticsearch 6.x, there can be only one type per index. If you try to specify a new type for an existing index that already has another type, Firehose returns an error during runtime. If you upgrade Elasticsearch from 6.x to 7.x and dont update your Firehose stream, Firehose still delivers data to Elastic- search with the old index name and type name. If you want to up- date your Firehose stream with a new index name, provide an empty string for TypeName. Constraints: o min: 0 o max: 100 o pattern: .* IndexRotationPeriod -&gt; (string) The Amazon OpenSearch Service index rotation period. Index rota- tion appends a timestamp to IndexName to facilitate the expira- tion of old data. Possible values: o NoRotation o OneHour o OneDay o OneWeek o OneMonth BufferingHints -&gt; (structure) The buffering options. If no value is specified, Ama- zonopensearchBufferingHints object default values are used. IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The default value is 300 (5 minutes). Constraints: o min: 0 o max: 900 SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MBs, before delivering it to the destination. The default value is 5. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typically ingest data at 1 MB/sec, the value should be 10 MB or higher. Constraints: o min: 1 o max: 100 RetryOptions -&gt; (structure) The retry behavior in case Firehose is unable to deliver docu- ments to Amazon OpenSearch Service. The default value is 300 (5 minutes). DurationInSeconds -&gt; (integer) After an initial failure to deliver to Amazon OpenSearch Ser- vice, the total amount of time during which Firehose retries delivery (including the first attempt). After this time has elapsed, the failed documents are written to Amazon S3. De- fault value is 300 seconds (5 minutes). A value of 0 (zero) results in no retries. Constraints: o min: 0 o max: 7200 S3Update -&gt; (structure) Describes an update for a destination in Amazon S3. RoleARN -&gt; (string) The Amazon Resource Name (ARN) of the Amazon Web Services credentials. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ BucketARN -&gt; (string) The ARN of the S3 bucket. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Name- spaces . Constraints: o min: 1 o max: 2048 o pattern: arn:.*:s3:::[\w\.\-]{1,255} Prefix -&gt; (string) The "YYYY/MM/DD/HH" time format prefix is automatically used for delivered Amazon S3 files. You can also specify a custom prefix, as described in Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* ErrorOutputPrefix -&gt; (string) A prefix that Firehose evaluates and adds to failed records before writing them to S3. This prefix appears immediately following the bucket name. For information about how to spec- ify this prefix, see Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* BufferingHints -&gt; (structure) The buffering option. If no value is specified, BufferingH- ints object default values are used. SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MiBs, be- fore delivering it to the destination. The default value is 5. This parameter is optional but if you specify a value for it, you must also specify a value for Inter- valInSeconds , and vice versa. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typi- cally ingest data at 1 MiB/sec, the value should be 10 MiB or higher. Constraints: o min: 1 o max: 128 IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The de- fault value is 300. This parameter is optional but if you specify a value for it, you must also specify a value for SizeInMBs , and vice versa. Constraints: o min: 0 o max: 900 CompressionFormat -&gt; (string) The compression format. If no value is specified, the default is UNCOMPRESSED . The compression formats SNAPPY or ZIP cannot be specified for Amazon Redshift destinations because they are not supported by the Amazon Redshift COPY operation that reads from the S3 bucket. Possible values: o UNCOMPRESSED o GZIP o ZIP o Snappy o HADOOP_SNAPPY EncryptionConfiguration -&gt; (structure) The encryption configuration. If no value is specified, the default is no encryption. NoEncryptionConfig -&gt; (string) Specifically override existing encryption information to ensure that no encryption is used. Possible values: o NoEncryption KMSEncryptionConfig -&gt; (structure) The encryption key. AWSKMSKeyARN -&gt; (string) [required] The Amazon Resource Name (ARN) of the encryption key. Must belong to the same Amazon Web Services Region as the destination Amazon S3 bucket. For more informa- tion, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:kms:[a-zA-Z0-9\-]+:\d{12}:(key|alias)/[a-zA-Z_0-9+=,.@\-_/]+ CloudWatchLoggingOptions -&gt; (structure) The CloudWatch logging options for your Firehose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* ProcessingConfiguration -&gt; (structure) Describes a data processing configuration. Enabled -&gt; (boolean) Enables or disables data processing. Processors -&gt; (list) The data processors. (structure) Describes a data processor. NOTE: If you want to add a new line delimiter between records in objects that are delivered to Amazon S3, choose AppendDelimiterToRecord as a processor type. You dont have to put a processor parameter when you select AppendDelimiterToRecord . Type -&gt; (string) [required] The type of processor. Possible values: o RecordDeAggregation o Decompression o CloudWatchLogProcessing o Lambda o MetadataExtraction o AppendDelimiterToRecord Parameters -&gt; (list) The processor parameters. (structure) Describes the processor parameter. ParameterName -&gt; (string) [required] The name of the parameter. Currently the fol- lowing default values are supported: 3 for Num- berOfRetries and 60 for the BufferIntervalIn- Seconds . The BufferSizeInMBs ranges between 0.2 MB and up to 3MB. The default buffering hint is 1MB for all destinations, except Splunk. For Splunk, the default buffering hint is 256 KB. Possible values: o LambdaArn o NumberOfRetries o MetadataExtractionQuery o JsonParsingEngine o RoleArn o BufferSizeInMBs o BufferIntervalInSeconds o SubRecordType o Delimiter o CompressionFormat o DataMessageExtraction ParameterValue -&gt; (string) [required] The parameter value. Constraints: o min: 1 o max: 5120 o pattern: ^(?!\s*$).+ CloudWatchLoggingOptions -&gt; (structure) Describes the Amazon CloudWatch logging options for your Fire- hose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* DocumentIdOptions -&gt; (structure) Indicates the method for setting up document ID. The supported methods are Firehose generated document ID and OpenSearch Ser- vice generated document ID. DefaultDocumentIdFormat -&gt; (string) [required] When the FIREHOSE_DEFAULT option is chosen, Firehose gener- ates a unique document ID for each record based on a unique internal identifier. The generated document ID is stable across multiple delivery attempts, which helps prevent the same record from being indexed multiple times with different document IDs. When the NO_DOCUMENT_ID option is chosen, Firehose does not include any document IDs in the requests it sends to the Ama- zon OpenSearch Service. This causes the Amazon OpenSearch Service domain to generate document IDs. In case of multiple delivery attempts, this may cause the same record to be in- dexed more than once with different document IDs. This option enables write-heavy operations, such as the ingestion of logs and observability data, to consume less resources in the Ama- zon OpenSearch Service domain, resulting in improved perfor- mance. Possible values: o FIREHOSE_DEFAULT o NO_DOCUMENT_ID JSON Syntax: { "RoleARN": "string", "DomainARN": "string", "ClusterEndpoint": "string", "IndexName": "string", "TypeName": "string", "IndexRotationPeriod": "NoRotation"|"OneHour"|"OneDay"|"OneWeek"|"OneMonth", "BufferingHints": { "IntervalInSeconds": integer, "SizeInMBs": integer }, "RetryOptions": { "DurationInSeconds": integer }, "S3Update": { "RoleARN": "string", "BucketARN": "string", "Prefix": "string", "ErrorOutputPrefix": "string", "BufferingHints": { "SizeInMBs": integer, "IntervalInSeconds": integer }, "CompressionFormat": "UNCOMPRESSED"|"GZIP"|"ZIP"|"Snappy"|"HADOOP_SNAPPY", "EncryptionConfiguration": { "NoEncryptionConfig": "NoEncryption", "KMSEncryptionConfig": { "AWSKMSKeyARN": "string" } }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" } }, "ProcessingConfiguration": { "Enabled": true|false, "Processors": [ { "Type": "RecordDeAggregation"|"Decompression"|"CloudWatchLogProcessing"|"Lambda"|"MetadataExtraction"|"AppendDelimiterToRecord", "Parameters": [ { "ParameterName": "LambdaArn"|"NumberOfRetries"|"MetadataExtractionQuery"|"JsonParsingEngine"|"RoleArn"|"BufferSizeInMBs"|"BufferIntervalInSeconds"|"SubRecordType"|"Delimiter"|"CompressionFormat"|"DataMessageExtraction", "ParameterValue": "string" } ... ] } ... ] }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" }, "DocumentIdOptions": { "DefaultDocumentIdFormat": "FIREHOSE_DEFAULT"|"NO_DOCUMENT_ID" } }
    /// </summary>
    [CliOption("--amazonopensearchservice-destination-update")]
    public string? AmazonopensearchserviceDestinationUpdate { get; set; }

    /// <summary>
    /// Describes an update for a destination in Splunk. HECEndpoint -&gt; (string) The HTTP Event Collector (HEC) endpoint to which Firehose sends your data. Constraints: o min: 0 o max: 2048 o pattern: .* HECEndpointType -&gt; (string) This type can be either "Raw" or "Event." Possible values: o Raw o Event HECToken -&gt; (string) A GUID that you obtain from your Splunk cluster when you create a new HEC endpoint. Constraints: o min: 0 o max: 2048 o pattern: .* HECAcknowledgmentTimeoutInSeconds -&gt; (integer) The amount of time that Firehose waits to receive an acknowledg- ment from Splunk after it sends data. At the end of the timeout period, Firehose either tries to send the data again or consid- ers it an error, based on your retry settings. Constraints: o min: 180 o max: 600 RetryOptions -&gt; (structure) The retry behavior in case Firehose is unable to deliver data to Splunk or if it doesn't receive an acknowledgment of receipt from Splunk. DurationInSeconds -&gt; (integer) The total amount of time that Firehose spends on retries. This duration starts after the initial attempt to send data to Splunk fails. It doesn't include the periods during which Firehose waits for acknowledgment from Splunk after each at- tempt. Constraints: o min: 0 o max: 7200 S3BackupMode -&gt; (string) Specifies how you want Firehose to back up documents to Amazon S3. When set to FailedDocumentsOnly , Firehose writes any data that could not be indexed to the configured Amazon S3 destina- tion. When set to AllEvents , Firehose delivers all incoming records to Amazon S3, and also writes failed documents to Amazon S3. The default value is FailedEventsOnly . You can update this backup mode from FailedEventsOnly to Al- lEvents . You can't update it from AllEvents to FailedEventsOnly . Possible values: o FailedEventsOnly o AllEvents S3Update -&gt; (structure) Your update to the configuration of the backup Amazon S3 loca- tion. RoleARN -&gt; (string) The Amazon Resource Name (ARN) of the Amazon Web Services credentials. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ BucketARN -&gt; (string) The ARN of the S3 bucket. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Name- spaces . Constraints: o min: 1 o max: 2048 o pattern: arn:.*:s3:::[\w\.\-]{1,255} Prefix -&gt; (string) The "YYYY/MM/DD/HH" time format prefix is automatically used for delivered Amazon S3 files. You can also specify a custom prefix, as described in Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* ErrorOutputPrefix -&gt; (string) A prefix that Firehose evaluates and adds to failed records before writing them to S3. This prefix appears immediately following the bucket name. For information about how to spec- ify this prefix, see Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* BufferingHints -&gt; (structure) The buffering option. If no value is specified, BufferingH- ints object default values are used. SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MiBs, be- fore delivering it to the destination. The default value is 5. This parameter is optional but if you specify a value for it, you must also specify a value for Inter- valInSeconds , and vice versa. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typi- cally ingest data at 1 MiB/sec, the value should be 10 MiB or higher. Constraints: o min: 1 o max: 128 IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The de- fault value is 300. This parameter is optional but if you specify a value for it, you must also specify a value for SizeInMBs , and vice versa. Constraints: o min: 0 o max: 900 CompressionFormat -&gt; (string) The compression format. If no value is specified, the default is UNCOMPRESSED . The compression formats SNAPPY or ZIP cannot be specified for Amazon Redshift destinations because they are not supported by the Amazon Redshift COPY operation that reads from the S3 bucket. Possible values: o UNCOMPRESSED o GZIP o ZIP o Snappy o HADOOP_SNAPPY EncryptionConfiguration -&gt; (structure) The encryption configuration. If no value is specified, the default is no encryption. NoEncryptionConfig -&gt; (string) Specifically override existing encryption information to ensure that no encryption is used. Possible values: o NoEncryption KMSEncryptionConfig -&gt; (structure) The encryption key. AWSKMSKeyARN -&gt; (string) [required] The Amazon Resource Name (ARN) of the encryption key. Must belong to the same Amazon Web Services Region as the destination Amazon S3 bucket. For more informa- tion, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:kms:[a-zA-Z0-9\-]+:\d{12}:(key|alias)/[a-zA-Z_0-9+=,.@\-_/]+ CloudWatchLoggingOptions -&gt; (structure) The CloudWatch logging options for your Firehose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* ProcessingConfiguration -&gt; (structure) The data processing configuration. Enabled -&gt; (boolean) Enables or disables data processing. Processors -&gt; (list) The data processors. (structure) Describes a data processor. NOTE: If you want to add a new line delimiter between records in objects that are delivered to Amazon S3, choose AppendDelimiterToRecord as a processor type. You dont have to put a processor parameter when you select AppendDelimiterToRecord . Type -&gt; (string) [required] The type of processor. Possible values: o RecordDeAggregation o Decompression o CloudWatchLogProcessing o Lambda o MetadataExtraction o AppendDelimiterToRecord Parameters -&gt; (list) The processor parameters. (structure) Describes the processor parameter. ParameterName -&gt; (string) [required] The name of the parameter. Currently the fol- lowing default values are supported: 3 for Num- berOfRetries and 60 for the BufferIntervalIn- Seconds . The BufferSizeInMBs ranges between 0.2 MB and up to 3MB. The default buffering hint is 1MB for all destinations, except Splunk. For Splunk, the default buffering hint is 256 KB. Possible values: o LambdaArn o NumberOfRetries o MetadataExtractionQuery o JsonParsingEngine o RoleArn o BufferSizeInMBs o BufferIntervalInSeconds o SubRecordType o Delimiter o CompressionFormat o DataMessageExtraction ParameterValue -&gt; (string) [required] The parameter value. Constraints: o min: 1 o max: 5120 o pattern: ^(?!\s*$).+ CloudWatchLoggingOptions -&gt; (structure) The Amazon CloudWatch logging options for your Firehose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* BufferingHints -&gt; (structure) The buffering options. If no value is specified, the default values for Splunk are used. IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The default value is 60 (1 minute). Constraints: o min: 0 o max: 60 SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MBs, before delivering it to the destination. The default value is 5. Constraints: o min: 1 o max: 5 SecretsManagerConfiguration -&gt; (structure) The configuration that defines how you access secrets for Splunk. SecretARN -&gt; (string) The ARN of the secret that stores your credentials. It must be in the same region as the Firehose stream and the role. The secret ARN can reside in a different account than the Firehose stream and role as Firehose supports cross-account secret access. This parameter is required when Enabled is set to True . Constraints: o min: 1 o max: 2048 o pattern: arn:.*:secretsmanager:[a-zA-Z0-9\-]+:\d{12}:se- cret:[a-zA-Z0-9\-/_+=.@!]+ RoleARN -&gt; (string) Specifies the role that Firehose assumes when calling the Se- crets Manager API operation. When you provide the role, it overrides any destination specific role defined in the desti- nation configuration. If you do not provide the then we use the destination specific role. This parameter is required for Splunk. Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ Enabled -&gt; (boolean) [required] Specifies whether you want to use the secrets manager fea- ture. When set as True the secrets manager configuration overwrites the existing secrets in the destination configura- tion. When it's set to False Firehose falls back to the cre- dentials in the destination configuration. JSON Syntax: { "HECEndpoint": "string", "HECEndpointType": "Raw"|"Event", "HECToken": "string", "HECAcknowledgmentTimeoutInSeconds": integer, "RetryOptions": { "DurationInSeconds": integer }, "S3BackupMode": "FailedEventsOnly"|"AllEvents", "S3Update": { "RoleARN": "string", "BucketARN": "string", "Prefix": "string", "ErrorOutputPrefix": "string", "BufferingHints": { "SizeInMBs": integer, "IntervalInSeconds": integer }, "CompressionFormat": "UNCOMPRESSED"|"GZIP"|"ZIP"|"Snappy"|"HADOOP_SNAPPY", "EncryptionConfiguration": { "NoEncryptionConfig": "NoEncryption", "KMSEncryptionConfig": { "AWSKMSKeyARN": "string" } }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" } }, "ProcessingConfiguration": { "Enabled": true|false, "Processors": [ { "Type": "RecordDeAggregation"|"Decompression"|"CloudWatchLogProcessing"|"Lambda"|"MetadataExtraction"|"AppendDelimiterToRecord", "Parameters": [ { "ParameterName": "LambdaArn"|"NumberOfRetries"|"MetadataExtractionQuery"|"JsonParsingEngine"|"RoleArn"|"BufferSizeInMBs"|"BufferIntervalInSeconds"|"SubRecordType"|"Delimiter"|"CompressionFormat"|"DataMessageExtraction", "ParameterValue": "string" } ... ] } ... ] }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" }, "BufferingHints": { "IntervalInSeconds": integer, "SizeInMBs": integer }, "SecretsManagerConfiguration": { "SecretARN": "string", "RoleARN": "string", "Enabled": true|false } }
    /// </summary>
    [CliOption("--splunk-destination-update")]
    public string? SplunkDestinationUpdate { get; set; }

    /// <summary>
    /// Describes an update to the specified HTTP endpoint destination. EndpointConfiguration -&gt; (structure) Describes the configuration of the HTTP endpoint destination. Url -&gt; (string) [required] The URL of the HTTP endpoint selected as the destination. WARNING: If you choose an HTTP endpoint as your destination, re- view and follow the instructions in the Appendix - HTTP Endpoint Delivery Request and Response Specifications . Constraints: o min: 1 o max: 1000 o pattern: https://.* Name -&gt; (string) The name of the HTTP endpoint selected as the destination. Constraints: o min: 1 o max: 256 o pattern: ^(?!\s*$).+ AccessKey -&gt; (string) The access key required for Kinesis Firehose to authenticate with the HTTP endpoint selected as the destination. Constraints: o min: 0 o max: 4096 o pattern: .* BufferingHints -&gt; (structure) Describes buffering options that can be applied to the data be- fore it is delivered to the HTTPS endpoint destination. Firehose teats these options as hints, and it might choose to use more optimal values. The SizeInMBs and IntervalInSeconds parameters are optional. However, if specify a value for one of them, you must also provide a value for the other. SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MBs, before delivering it to the destination. The default value is 5. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typically ingest data at 1 MB/sec, the value should be 10 MB or higher. Constraints: o min: 1 o max: 64 IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The default value is 300 (5 minutes). Constraints: o min: 0 o max: 900 CloudWatchLoggingOptions -&gt; (structure) Describes the Amazon CloudWatch logging options for your Fire- hose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* RequestConfiguration -&gt; (structure) The configuration of the request sent to the HTTP endpoint spec- ified as the destination. ContentEncoding -&gt; (string) Firehose uses the content encoding to compress the body of a request before sending the request to the destination. For more information, see Content-Encoding in MDN Web Docs, the official Mozilla documentation. Possible values: o NONE o GZIP CommonAttributes -&gt; (list) Describes the metadata sent to the HTTP endpoint destination. Constraints: o min: 0 o max: 50 (structure) Describes the metadata that's delivered to the specified HTTP endpoint destination. AttributeName -&gt; (string) [required] The name of the HTTP endpoint common attribute. Constraints: o min: 1 o max: 256 o pattern: ^(?!\s*$).+ AttributeValue -&gt; (string) [required] The value of the HTTP endpoint common attribute. Constraints: o min: 0 o max: 1024 o pattern: .* ProcessingConfiguration -&gt; (structure) Describes a data processing configuration. Enabled -&gt; (boolean) Enables or disables data processing. Processors -&gt; (list) The data processors. (structure) Describes a data processor. NOTE: If you want to add a new line delimiter between records in objects that are delivered to Amazon S3, choose AppendDelimiterToRecord as a processor type. You dont have to put a processor parameter when you select AppendDelimiterToRecord . Type -&gt; (string) [required] The type of processor. Possible values: o RecordDeAggregation o Decompression o CloudWatchLogProcessing o Lambda o MetadataExtraction o AppendDelimiterToRecord Parameters -&gt; (list) The processor parameters. (structure) Describes the processor parameter. ParameterName -&gt; (string) [required] The name of the parameter. Currently the fol- lowing default values are supported: 3 for Num- berOfRetries and 60 for the BufferIntervalIn- Seconds . The BufferSizeInMBs ranges between 0.2 MB and up to 3MB. The default buffering hint is 1MB for all destinations, except Splunk. For Splunk, the default buffering hint is 256 KB. Possible values: o LambdaArn o NumberOfRetries o MetadataExtractionQuery o JsonParsingEngine o RoleArn o BufferSizeInMBs o BufferIntervalInSeconds o SubRecordType o Delimiter o CompressionFormat o DataMessageExtraction ParameterValue -&gt; (string) [required] The parameter value. Constraints: o min: 1 o max: 5120 o pattern: ^(?!\s*$).+ RoleARN -&gt; (string) Firehose uses this IAM role for all the permissions that the de- livery stream needs. Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ RetryOptions -&gt; (structure) Describes the retry behavior in case Firehose is unable to de- liver data to the specified HTTP endpoint destination, or if it doesn't receive a valid acknowledgment of receipt from the spec- ified HTTP endpoint destination. DurationInSeconds -&gt; (integer) The total amount of time that Firehose spends on retries. This duration starts after the initial attempt to send data to the custom destination via HTTPS endpoint fails. It doesn't include the periods during which Firehose waits for acknowledgment from the specified destination after each at- tempt. Constraints: o min: 0 o max: 7200 S3BackupMode -&gt; (string) Describes the S3 bucket backup options for the data that Kinesis Firehose delivers to the HTTP endpoint destination. You can back up all documents (AllData ) or only the documents that Firehose could not deliver to the specified HTTP endpoint destination (FailedDataOnly ). Possible values: o FailedDataOnly o AllData S3Update -&gt; (structure) Describes an update for a destination in Amazon S3. RoleARN -&gt; (string) The Amazon Resource Name (ARN) of the Amazon Web Services credentials. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ BucketARN -&gt; (string) The ARN of the S3 bucket. For more information, see Amazon Resource Names (ARNs) and Amazon Web Services Service Name- spaces . Constraints: o min: 1 o max: 2048 o pattern: arn:.*:s3:::[\w\.\-]{1,255} Prefix -&gt; (string) The "YYYY/MM/DD/HH" time format prefix is automatically used for delivered Amazon S3 files. You can also specify a custom prefix, as described in Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* ErrorOutputPrefix -&gt; (string) A prefix that Firehose evaluates and adds to failed records before writing them to S3. This prefix appears immediately following the bucket name. For information about how to spec- ify this prefix, see Custom Prefixes for Amazon S3 Objects . Constraints: o min: 0 o max: 1024 o pattern: .* BufferingHints -&gt; (structure) The buffering option. If no value is specified, BufferingH- ints object default values are used. SizeInMBs -&gt; (integer) Buffer incoming data to the specified size, in MiBs, be- fore delivering it to the destination. The default value is 5. This parameter is optional but if you specify a value for it, you must also specify a value for Inter- valInSeconds , and vice versa. We recommend setting this parameter to a value greater than the amount of data you typically ingest into the Firehose stream in 10 seconds. For example, if you typi- cally ingest data at 1 MiB/sec, the value should be 10 MiB or higher. Constraints: o min: 1 o max: 128 IntervalInSeconds -&gt; (integer) Buffer incoming data for the specified period of time, in seconds, before delivering it to the destination. The de- fault value is 300. This parameter is optional but if you specify a value for it, you must also specify a value for SizeInMBs , and vice versa. Constraints: o min: 0 o max: 900 CompressionFormat -&gt; (string) The compression format. If no value is specified, the default is UNCOMPRESSED . The compression formats SNAPPY or ZIP cannot be specified for Amazon Redshift destinations because they are not supported by the Amazon Redshift COPY operation that reads from the S3 bucket. Possible values: o UNCOMPRESSED o GZIP o ZIP o Snappy o HADOOP_SNAPPY EncryptionConfiguration -&gt; (structure) The encryption configuration. If no value is specified, the default is no encryption. NoEncryptionConfig -&gt; (string) Specifically override existing encryption information to ensure that no encryption is used. Possible values: o NoEncryption KMSEncryptionConfig -&gt; (structure) The encryption key. AWSKMSKeyARN -&gt; (string) [required] The Amazon Resource Name (ARN) of the encryption key. Must belong to the same Amazon Web Services Region as the destination Amazon S3 bucket. For more informa- tion, see Amazon Resource Names (ARNs) and Amazon Web Services Service Namespaces . Constraints: o min: 1 o max: 512 o pattern: arn:.*:kms:[a-zA-Z0-9\-]+:\d{12}:(key|alias)/[a-zA-Z_0-9+=,.@\-_/]+ CloudWatchLoggingOptions -&gt; (structure) The CloudWatch logging options for your Firehose stream. Enabled -&gt; (boolean) Enables or disables CloudWatch logging. LogGroupName -&gt; (string) The CloudWatch group name for logging. This value is re- quired if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [\.\-_/#A-Za-z0-9]* LogStreamName -&gt; (string) The CloudWatch log stream name for logging. This value is required if CloudWatch logging is enabled. Constraints: o min: 0 o max: 512 o pattern: [^:*]* SecretsManagerConfiguration -&gt; (structure) The configuration that defines how you access secrets for HTTP Endpoint destination. SecretARN -&gt; (string) The ARN of the secret that stores your credentials. It must be in the same region as the Firehose stream and the role. The secret ARN can reside in a different account than the Firehose stream and role as Firehose supports cross-account secret access. This parameter is required when Enabled is set to True . Constraints: o min: 1 o max: 2048 o pattern: arn:.*:secretsmanager:[a-zA-Z0-9\-]+:\d{12}:se- cret:[a-zA-Z0-9\-/_+=.@!]+ RoleARN -&gt; (string) Specifies the role that Firehose assumes when calling the Se- crets Manager API operation. When you provide the role, it overrides any destination specific role defined in the desti- nation configuration. If you do not provide the then we use the destination specific role. This parameter is required for Splunk. Constraints: o min: 1 o max: 512 o pattern: arn:.*:iam::\d{12}:role/[a-zA-Z_0-9+=,.@\-_/]+ Enabled -&gt; (boolean) [required] Specifies whether you want to use the secrets manager fea- ture. When set as True the secrets manager configuration overwrites the existing secrets in the destination configura- tion. When it's set to False Firehose falls back to the cre- dentials in the destination configuration. JSON Syntax: { "EndpointConfiguration": { "Url": "string", "Name": "string", "AccessKey": "string" }, "BufferingHints": { "SizeInMBs": integer, "IntervalInSeconds": integer }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" }, "RequestConfiguration": { "ContentEncoding": "NONE"|"GZIP", "CommonAttributes": [ { "AttributeName": "string", "AttributeValue": "string" } ... ] }, "ProcessingConfiguration": { "Enabled": true|false, "Processors": [ { "Type": "RecordDeAggregation"|"Decompression"|"CloudWatchLogProcessing"|"Lambda"|"MetadataExtraction"|"AppendDelimiterToRecord", "Parameters": [ { "ParameterName": "LambdaArn"|"NumberOfRetries"|"MetadataExtractionQuery"|"JsonParsingEngine"|"RoleArn"|"BufferSizeInMBs"|"BufferIntervalInSeconds"|"SubRecordType"|"Delimiter"|"CompressionFormat"|"DataMessageExtraction", "ParameterValue": "string" } ... ] } ... ] }, "RoleARN": "string", "RetryOptions": { "DurationInSeconds": integer }, "S3BackupMode": "FailedDataOnly"|"AllData", "S3Update": { "RoleARN": "string", "BucketARN": "string", "Prefix": "string", "ErrorOutputPrefix": "string", "BufferingHints": { "SizeInMBs": integer, "IntervalInSeconds": integer }, "CompressionFormat": "UNCOMPRESSED"|"GZIP"|"ZIP"|"Snappy"|"HADOOP_SNAPPY", "EncryptionConfiguration": { "NoEncryptionConfig": "NoEncryption", "KMSEncryptionConfig": { "AWSKMSKeyARN": "string" } }, "CloudWatchLoggingOptions": { "Enabled": true|false, "LogGroupName": "string", "LogStreamName": "string" } }, "SecretsManagerConfiguration": { "SecretARN": "string", "RoleARN": "string", "Enabled": true|false } }
    /// </summary>
    [CliOption("--http-endpoint-destination-update")]
    public string? HttpEndpointDestinationUpdate { get; set; }

